contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target) public {
        require(target != address(0));
        c.mintToken(address(this), 100); if (__ESBMC_reverted()) return;
        bool before = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        require(before == false);
        c.freezeAccount(target, true); if (__ESBMC_reverted()) return;
        bool frozen = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        c.freezeAccount(target, false); if (__ESBMC_reverted()) return;
        bool unfrozen = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        assert(frozen == true && unfrozen == false);
    }
    receive() external payable {}
}

